--==============================================================================
-- 37_dmf0003_popup_metadata_handoff.sql
-- DMF0003 (MktFcst) Phase 2e — POPUP 메타데이터 handoff (적용 보류 — 사용자 검토 후 적용)
--
-- 배경: Phase 2e FE 구현(SspSyncCompare / SspSync / PR / PRHistory popup)이 BE 공용
--       proc 프레임워크(useTabProcQuery → PR_GET_PROC_INFO_LIST(mnuId,shtNm,btn)
--       → BTN_MPG → API_M → PROC_M positional bind)로 호출하려면 아래 3 테이블의
--       메타가 사내 Oracle 에 존재해야 한다. 2026-06-28 ora.py 실측 결과 0행 → 본 handoff.
--
-- 검증 실측(2026-06-28, ora.py / 121.162.245.167:2521/OCGSCMD_P01):
--   SP 존재(ALL_PROCEDURES):
--     DMF0003_GET_PRPOPUP                  (14 IN + O_RC1/O_RC2/O_RC3)  ✓
--     DMF0003_SAVE_PRPOPUP                 (20 IN + R_REQUEST_NO/R_ERROR_MSG OUT)  ✓
--     DMF0003_GET_PR_HISTORY_POPUP         (13 IN + O_RC1/O_RC2)  ✓
--     DMF0003_GET_MKT_FCST_COMPARE_POPUP   (8 IN + O_RC1/O_RC2)  ✓
--   메타 부재(전부 0행):
--     SCM_ADM_PROC_M       : 위 4 SP 모두 0행
--     SCM_ADM_API_M        : 위 4 SP routing 0행
--     SCM_ADM_MNU_BTN_MPG_M: DMF0003 의 prPopup/prHistory/sspCompare sheet 0행
--
-- 매핑 정책(자매 DMF0003 titleSet 표준 동일 — 022_fix_titleSet_btn_mpg.sql):
--   MNU_ID='DMF0003' + 신규 SHT_NM(prPopup/prHistory/sspCompare) + MNU_BTN_CD(SEARCH/SAVE)
--   → API_ID → API_URL=PROC_NM. (별도 popup MENU_ID 미생성 — DMF0003 내부 sheet 확장)
--   PROC_M COL_NM = camelCase (= FE procedures.d.ts request key + GET_PRPOPUP O_RC alias),
--     SORT_ORD = SP positional. createdBy 는 BE makeProcedure 세션 자동.
--
-- 멱등: NOT EXISTS / DELETE+INSERT. 검증: PROC_M 수 == SP USER_ARGUMENTS 수.
--==============================================================================
SET DEFINE OFF
SET SERVEROUTPUT ON
SET FEEDBACK ON
WHENEVER SQLERROR EXIT FAILURE

--------------------------------------------------------------------------------
-- 1) SCM_ADM_API_M — popup SP routing (API_URL = PROC_NM)
--------------------------------------------------------------------------------
INSERT INTO SCM_ADM_API_M (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN,
                            CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'DMF0003_prPopup_SEARCH', 'PROC', 'MSG_API_DMF0003_PR_SEARCH',
       'DMF0003 PR Popup Search', 'DMF0003_GET_PRPOPUP', 'Y',
       'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_API_M WHERE API_ID='DMF0003_prPopup_SEARCH');

