--------------------------------------------------------------------------------
-- 4) 권한 — DMF0003 의 기존 USER_GR (main sheet) 동적 복사 + ADMIN/DEMAND_USER/GUEST fallback
--    popup sheet 4종(prPopup SEARCH/SAVE, prHistory SEARCH, sspCompare SEARCH)
--------------------------------------------------------------------------------
INSERT INTO SCM_ADM_USER_GR_MNU_BTN_MPG_M (USER_GR_ID, MNU_ID, SHT_NM, MNU_BTN_CD, USE_YN,
                                            CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT u.USER_GR_ID, 'DMF0003', m.SHT_NM, m.MNU_BTN_CD, 'Y',
       'admin', SYSDATE, 'admin', SYSDATE
  FROM ( SELECT DISTINCT USER_GR_ID FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='DMF0003'
         UNION SELECT 'ADMIN' FROM DUAL
         UNION SELECT 'DEMAND_USER' FROM DUAL
         UNION SELECT 'GUEST' FROM DUAL ) u
 CROSS JOIN ( SELECT 'prPopup' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
              UNION ALL SELECT 'prPopup', 'SAVE' FROM DUAL
              UNION ALL SELECT 'prHistory', 'SEARCH' FROM DUAL
              UNION ALL SELECT 'sspCompare', 'SEARCH' FROM DUAL ) m
 WHERE NOT EXISTS (
   SELECT 1 FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M e
    WHERE e.USER_GR_ID=u.USER_GR_ID AND e.MNU_ID='DMF0003'
      AND e.SHT_NM=m.SHT_NM AND e.MNU_BTN_CD=m.MNU_BTN_CD );

COMMIT;

--------------------------------------------------------------------------------
-- 5) 검증 — PROC_M 수 == SP USER_ARGUMENTS 수 (positional 정합)
--------------------------------------------------------------------------------
PROMPT === PROC_M vs SP_ARGS 정합 검증 ===
SELECT p.PROC_NM,
       (SELECT COUNT(*) FROM SCM_ADM_PROC_M  WHERE PROC_NM=p.PROC_NM) PROC_M_CNT,
       (SELECT COUNT(*) FROM USER_ARGUMENTS  WHERE OBJECT_NAME=p.PROC_NM AND DATA_LEVEL=0) SP_ARG_CNT
  FROM (SELECT 'DMF0003_GET_PRPOPUP' PROC_NM FROM DUAL
        UNION ALL SELECT 'DMF0003_SAVE_PRPOPUP' FROM DUAL
        UNION ALL SELECT 'DMF0003_GET_PR_HISTORY_POPUP' FROM DUAL
        UNION ALL SELECT 'DMF0003_GET_MKT_FCST_COMPARE_POPUP' FROM DUAL) p;

EXIT;
